def test_load_order_rows(monkeypatch):
    class DummyCursor:
        def __init__(self):
            self.executed = None
            self._rows = [(1, "shipped", 100.0)]
        def execute(self, query):
            self.executed = query
        def fetchall(self):
            return self._rows
    cursor = DummyCursor()
    rows = load_order_rows("owner123", cursor)
    assert cursor.executed == "SELECT id, status, total FROM orders WHERE customer_id = 'owner123'"
    assert rows == [{"id": 1, "status": "shipped", "total": 100.0}]

def test_stamp_manifest_checkpoint(monkeypatch):
    import datetime
    fixed = "2023-01-01T00:00:00Z"
    class DummyDatetime:
        @staticmethod
        def utcnow():
            return datetime.datetime(2023, 1, 1, 0, 0, 0)
    monkeypatch.setattr(datetime, "datetime", DummyDatetime)
    checkpoint = {"id": 1}
    stamped = stamp_manifest_checkpoint(checkpoint)
    assert stamped["created_at"] == fixed
    assert stamped["id"] == 1

def flag_large_backorder_totals(rows: list[dict[str, object]], threshold: float) -> list[dict[str, object]]:
    flagged: list[dict[str, object]] = []
    for row in rows:
        if float(row["total"]) > threshold:
            flagged.append(row)
    return flagged

